from pathlib import Path
root=Path(__file__).resolve().parents[1]/'frontend/src/templates'
designs=[('RomanticFloral','amore'),('ElegantLuxury','noir'),('MinimalistWhite','pure'),('NusantaraHeritage','nusantara'),('GardenDream','garden'),('ClassicVintage','letters'),('MidnightRomance','dark'),('Sakinah','sakinah'),('EternalStory','cinema'),('Blush','daydream')]
for folder,design in designs:
 p=root/folder/'presentation.css';s=p.read_text(encoding='utf-8');s+=f'\n.design-{design} .design-cover h1,.design-{design} .design-hero h1{{font-size:clamp(2.5rem,var(--name-scale,15vw),6.4rem);letter-spacing:-.025em}}\n';p.write_text(s,encoding='utf-8')
p=root/'ElegantLuxury/presentation.css';s=p.read_text(encoding='utf-8');s+='\n@media(max-width:767px){.cover-noir{display:flex;flex-direction:column}.cover-noir .noir-title{text-align:center;padding:28px 25px;width:100%}.cover-noir h1 i{display:inline;margin:0 10px}.cover-noir .cover-photo{min-height:0;height:38svh}.cover-noir .cover-invitation{margin-top:0;padding:24px}.cover-noir .noir-title h1{font-size:clamp(2.3rem,var(--name-scale,14vw),4rem)}}\n';p.write_text(s,encoding='utf-8')
p=root/'NusantaraHeritage/presentation.css';s=p.read_text(encoding='utf-8');s+='\n.cover-nusantara .gate{width:50%;background:repeating-linear-gradient(45deg,#642831 0 14px,#9d7a421f 14px 15px)}.cover-nusantara .cover-title{position:relative;z-index:4}.cover-nusantara .gate-left{border-right:2px solid #c6a66c}.cover-nusantara .gate-right{border-left:2px solid #c6a66c}.cover-leave-active .gate-left{transform:translateX(-110%)}.cover-leave-active .gate-right{transform:translateX(110%)}\n';p.write_text(s,encoding='utf-8')
p=root/'ClassicVintage/presentation.css';s=p.read_text(encoding='utf-8');s+='\n.cover-letters .envelope-flap{transform-origin:top;transition:transform .7s ease}.cover-leave-active .envelope-flap{transform:rotateX(170deg)}.cover-leave-active .letter-sheet{transform:translateY(-50px) rotate(0);transition:transform .7s ease}\n';p.write_text(s,encoding='utf-8')
